BEGIN;
CREATE TABLE IF NOT EXISTS approval_workflows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workflow_code varchar(80) NOT NULL UNIQUE,workflow_name varchar(255) NOT NULL,module_name varchar(80) NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approval_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workflow_id uuid NOT NULL REFERENCES approval_workflows(id) ON DELETE CASCADE,sequence_number integer NOT NULL,role_id uuid REFERENCES roles(id),minimum_amount numeric(20,2),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workflow_id,sequence_number));
CREATE TABLE IF NOT EXISTS approval_instances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workflow_id uuid NOT NULL REFERENCES approval_workflows(id),record_type varchar(100) NOT NULL,record_id uuid NOT NULL,current_step integer NOT NULL DEFAULT 1,status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED','CANCELLED')),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE IF NOT EXISTS approval_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),instance_id uuid NOT NULL REFERENCES approval_instances(id) ON DELETE CASCADE,step_id uuid REFERENCES approval_steps(id),approver_id uuid REFERENCES users(id),action varchar(20) NOT NULL CHECK(action IN ('APPROVE','REJECT','RETURN','COMMENT')),comments text,action_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_type varchar(100) NOT NULL,record_id uuid NOT NULL,user_id uuid REFERENCES users(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_type varchar(100) NOT NULL,record_id uuid NOT NULL,document_id uuid NOT NULL REFERENCES documents(id),attached_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(record_type,record_id,document_id));
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,event_type varchar(100) NOT NULL,title varchar(255) NOT NULL,body text,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_approval_record ON approval_instances(record_type,record_id);
CREATE INDEX IF NOT EXISTS ix_notifications_user_unread ON notifications(user_id,created_at DESC) WHERE read_at IS NULL;
COMMIT;
